int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                     struct ieee80211_radiotap_header *radiotap_header,
                                     int max_length,
                                     const struct ieee80211_radiotap_vendor_namespaces *vns) {
    const uint8_t *cursor;
    uint32_t align;
    uint8_t *vendornull;
    uint32_t offset;
    const struct ieee80211_radiotap_vendor_namespaces *vn;
    uint32_t i;

    if (radiotap_header == NULL || iterator == NULL)
        return -EINVAL;

    cursor = (const uint8_t *)radiotap_header;
    cursor += sizeof(*radiotap_header);

    if (max_length < (int)(sizeof(*radiotap_header)))
        return -EINVAL;

    if ((radiotap_header->it_version & ~IEEE80211_RADIOTAP_VERS_MASK) != 0) {
        return -EINVAL;
    }

    iterator->radiotap_header = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->this_arg = NULL;
    iterator->is_radiotap = 1;
    iterator->is_aligned = 0;

    if (radiotap_header->it_version == 0) {
        if ((radiotap_header->it_present & IEEE80211_RADIOTAP_EXT) != 0) {
            uint32_t ext;

            for (ext = 0; ; ext++) {
                uint32_t extmap;
                if (ext == 0)
                    extmap = le32_to_cpu(radiotap_header->it_present_ext[ext]);
                else {
                    if ((cursor + sizeof(uint32_t)) > (const uint8_t *)(radiotap_header) + max_length)
                        return -EINVAL;

                    extmap = le32_to_cpu(*(uint32_t *)cursor);
                    cursor += sizeof(uint32_t);
                }

                if (extmap == 0)
                    break;

                for (i = 0; i < 32; i++) {
                    if (extmap & (1 << i)) {
                        iterator->present |= (1 << (IEEE80211_RADIOTAP_NUM_PRESENT + (ext * 32) + i));
                    }
                }
            }
        }

        iterator->present = le32_to_cpu(radiotap_header->it_present);
    } else {
        return -EINVAL;
    }

    iterator->cursor = cursor;
    iterator->align = 0;
    iterator->align = (uintptr_t)cursor % 4;
    iterator->vendornull = NULL;

    for (i = 0; i < IEEE80211_RADIOTAP_NUM_ITEMS; i++) {
        if (iterator->present & (1 << i)) {
            iterator->this_arg = &iterator->args[i];
            offset = iterator->cursor - (const uint8_t *)radiotap_header;
            iterator->this_arg->key = i;
            iterator->this_arg->arg = (void *)iterator->cursor;
            iterator->this_arg->is_aligned = (iterator->align == 0);
            iterator->cursor += iterator->this_arg->arg_length;
            iterator->present &= ~(1 << i);
            if ((const uint8_t *)iterator->cursor - (const uint8_t *)radiotap_header > (unsigned)max_length)
                return -EINVAL;

            continue;
        }
    }

    return 0;
}

int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                     const struct ieee80211_radiotap_header *radiotap_header,
                                     int max_length,
                                     const struct ieee80211_radiotap_vendor_namespaces *vns) {
    unsigned char *cursor;
    uint32_t present;

    if (!iterator || !radiotap_header || max_length < sizeof(*radiotap_header))
        return -EINVAL;

    iterator->hdr = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->is_present = 0;
    iterator->aligncheck = 0;
    iterator->current_type = IEEE80211_RADIOTAP_NO_FIELD;
    iterator->this_arg = NULL;
    iterator->arg_count = 0;

    if (radiotap_header->it_version != 0)
        return -EINVAL;

    present = le16_to_cpu(radiotap_header->it_present);

    if (present == 0)
        return -EINVAL;

    if (present & IEEE80211_RADIOTAP_EXT) {
        if (radiotap_header->it_len < 4)
            return -EINVAL;

        present = le32_to_cpu(*((uint32_t *)((unsigned char *)radiotap_header + 2)));
    }

    cursor = (unsigned char *)radiotap_header + sizeof(*radiotap_header);
    iterator->cursor = cursor;

    if ((cursor - (unsigned char *)radiotap_header) + sizeof(uint32_t) > max_length)
        return -EINVAL;

    iterator->is_present = present;

    return 0;
}

int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                     struct ieee80211_radiotap_header *radiotap_header,
                                     int max_length,
                                     const struct ieee80211_radiotap_vendor_namespaces *vns) {
    int ret = -EINVAL;

    if (!iterator || !radiotap_header) {
        return ret;
    }

    if (max_length < sizeof(struct ieee80211_radiotap_header)) {
        return ret;
    }

    iterator->hdr = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;

    iterator->cursor = 0;
    iterator->current_max_length = max_length;
    iterator->this_arg = NULL;
    iterator->is_first = 1;

    if (iterator->hdr->it_version != 0) {
        return ret;
    }

    iterator->arg = (uint8_t *)((uint8_t *)iterator->hdr + sizeof(struct ieee80211_radiotap_header));
    iterator->align = 0;

    if (iterator->hdr->it_present >> 31) {
        if ((iterator->cursor += sizeof(uint32_t)) > max_length) {
            return ret;
        }
        iterator->arg = (uint8_t *)((uint8_t *)iterator->arg + sizeof(uint32_t));
    }

    ret = 0;
    return ret;
}

int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                    struct ieee80211_radiotap_header *radiotap_header,
                                    int max_length,
                                    const struct ieee80211_radiotap_vendor_namespaces *vns) {
    int i;

    if (!iterator || !radiotap_header || max_length < RTAP_HDR_LEN) {
        return -EINVAL;
    }

    iterator->i_hdr = radiotap_header;
    iterator->i_error = 0;
    iterator->i_current_node = 0;
    iterator->i_cursor = RTAP_HDR_LEN;
    iterator->i_max_length = max_length;
    iterator->i_vns = vns;

    if (iterator->i_hdr->it_version != 0) {
        iterator->i_error = -EINVAL;
        return -EINVAL;
    }

    if (iterator->i_hdr->it_pad != 0) {
        iterator->i_error = -EINVAL;
        return -EINVAL;
    }

    for (i = 0; i < 8; i++) {
        iterator->i_bitmap[i] = le64toh(iterator->i_hdr->it_present[i]);
    }

    return 0;
}

int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                    struct ieee80211_radiotap_header *radiotap_header,
                                    int max_length,
                                    const struct ieee80211_radiotap_vendor_namespaces *vns) {
    uint8_t *cursor;

    if (!iterator || !radiotap_header) {
        return -EINVAL;
    }

    if (max_length < RTAP_HDR_LEN) {
        return -EINVAL;
    }

    cursor = (uint8_t *)radiotap_header;
    iterator->hdr = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->this_arg = NULL;
    iterator->is_radiotap = 1;

    if (iterator->hdr->it_version != 0) {
        return -EINVAL;
    }

    iterator->current = cursor + RTAP_HDR_LEN;
    iterator->align = 0;

    return 0;
}
